CREATE TABLE IF NOT EXISTS officer_work_credentials(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,faction_id INTEGER NOT NULL,ciphertext TEXT,iv TEXT,capabilities TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS officer_work_credential_owner ON officer_work_credentials(user_id,faction_id,revoked);
CREATE TABLE IF NOT EXISTS officer_work_jobs(id TEXT PRIMARY KEY,faction_id INTEGER NOT NULL,user_id INTEGER NOT NULL,credential_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('snapshot','report')),label TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Scheduled','Running','Completed','Failed','Cancelled')),scheduled_at INTEGER NOT NULL,next_run INTEGER NOT NULL,lease_token TEXT,lease_until INTEGER,attempts INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,progress TEXT NOT NULL,definition TEXT NOT NULL,manifest_key TEXT,quality TEXT,error_code TEXT,error_message TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS officer_work_due ON officer_work_jobs(status,next_run,lease_until);
CREATE INDEX IF NOT EXISTS officer_work_search ON officer_work_jobs(faction_id,kind,scheduled_at,created_at);
CREATE TABLE IF NOT EXISTS officer_work_audit(id TEXT PRIMARY KEY,faction_id INTEGER NOT NULL,user_id INTEGER NOT NULL,job_id TEXT,event TEXT NOT NULL,details TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS officer_work_rate(user_id INTEGER NOT NULL,minute INTEGER NOT NULL,calls INTEGER NOT NULL,PRIMARY KEY(user_id,minute));
